#!/usr/bin/env python3
"""Exercise OTP bridge callbacks using a local synthetic verifier, A/B."""
from pathlib import Path
import subprocess,tempfile,shlex
r=Path(__file__).resolve().parents[2];a=(r/'tests/bridge_refactor_fixtures/verify_otp_before.inc').read_text();b=(r/'src/bridge/DecodiumBridgeFoxVerifier.cpp').read_text().split('\n\n',1)[1];assert a==b
h='''#include <QObject>\n#include <QString>\n#include <QDateTime>\n#include <QTimer>\n#include <cassert>\n#define FOXVERIFIER_DEFAULT_BASE_URL "https://www.9dx.cc"\nclass FoxVerifier:public QObject { Q_OBJECT public: static int count; static unsigned lastHz; static QString lastCall; FoxVerifier(QString,void*,QString,QString c,QDateTime t,QString code,unsigned hz):QObject(nullptr){++count;lastHz=hz;lastCall=c;QTimer::singleShot(0,this,[this,c,t,code,hz]{if(code=="good") emit verifyComplete(200,t,c,code,hz,"accepted");else emit verifyError(500,t,c,code,hz,"failed");});} signals: void verifyComplete(int,QDateTime,QString,QString,unsigned,QString);void verifyError(int,QDateTime,QString,QString,unsigned,QString);}; int FoxVerifier::count=0;unsigned FoxVerifier::lastHz=0;QString FoxVerifier::lastCall;\nclass DecodiumBridge:public QObject {Q_OBJECT public:QStringList results;void verifyOtp(const QString&,const QString&,int);signals:void statusMessage(QString);};\n'''
t='''\n#include "moc.cpp"\n#include <QCoreApplication>\nint main(int argc,char**argv){QCoreApplication app(argc,argv);DecodiumBridge b;QObject::connect(&b,&DecodiumBridge::statusMessage,&b,[&](QString s){b.results<<s;});b.verifyOtp("", "good", 1);b.verifyOtp("K1ABC", "", 1);assert(FoxVerifier::count==0);b.verifyOtp("K1ABC","good",0);assert(FoxVerifier::lastHz==750);b.verifyOtp("W1AW","bad",1200);assert(FoxVerifier::count==2&&FoxVerifier::lastHz==1200&&FoxVerifier::lastCall=="W1AW");QTimer::singleShot(50,&app,&QCoreApplication::quit);app.exec();assert(b.results.size()==2);assert(b.results[0].contains("Fox OTP OK: K1ABC")&&b.results[1].contains("Fox OTP FAIL: W1AW"));}\n'''
flags=shlex.split(subprocess.check_output(['pkg-config','--cflags','--libs','Qt6Core'],text=True));moc=subprocess.check_output(['qtpaths','--query','QT_INSTALL_LIBEXECS'],text=True).strip()+'/moc'
with tempfile.TemporaryDirectory(prefix='decodium-otp-ab-') as tmp:
 d=Path(tmp)
 for label,body in [('A',a),('B',b)]:
  p=d/(label+'.cpp');p.write_text(h+body+t);subprocess.run([moc,str(p),'-o',str(d/'moc.cpp')],check=True);exe=d/label;subprocess.run(['c++','-std=c++17',str(p),*flags,'-o',str(exe)],check=True);subprocess.run([str(exe)],check=True);print(label,'OK')
